    html=html[:html.index('<main>')]+new+html[html.index('</main>')+len('</main>'):]
    html=html.replace('</style><aside','</style><aside',1)
    html=html.replace('<aside class="app-sidebar">','<style>'+ (ASSETS/'workspace.css').read_text()+'</style><aside class="app-sidebar">',1)
